import{z as i,x as B,o as s,c as T,q as r,j as A,D as t,d as E,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"方法、幂等与缓存头","description":"","frontmatter":{"title":"方法、幂等与缓存头","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/http-semantics.md","filePath":"cs/http-semantics.md","lastUpdated":1791063341000}'),d={name:"cs/http-semantics.md"};function p(C,a,c,m,D,h){const o=B("Mermaid");return s(),T("div",null,[a[2]||(a[2]=r('<h1 id="方法、幂等与缓存头" tabindex="-1">方法、幂等与缓存头 <a class="header-anchor" href="#方法、幂等与缓存头" aria-label="Permalink to &quot;方法、幂等与缓存头&quot;">​</a></h1><div class="epigraph"><p>方法约定对资源做什么；幂等与安全限制重试能否自动发生。缓存头告诉中间人这份表示能不能存、能存多久。</p><footer>—— 据 Fielding 等, RFC 9110, HTTP Semantics, 2022；Kurose and Ross</footer></div><p><a href="/cs/http">上一课</a>给出请求–响应：方法、目标、头、状态码。本课不重画一行请求。缺口是语义合同：GET 与 PUT 能否被代理重试、中间盒按什么头缓存。没有这些，后课 HTTP/2 多路只是换了帧，CDN 也不知道什么能复制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/http">HTTP</a> 留下方法名。安全方法（GET、HEAD）不应有副作用；幂等方法（含 PUT、DELETE）同一请求重复一次与多次效果相当。POST 通常既不安全也不幂等，丢了不能由中间人盲目重放。<code>Cache-Control</code>、<code>ETag</code>、条件请求决定表示是否可复用。缺口是<strong>重试与缓存的合法性</strong>，不是 TLS 记录。</p><p><span class="marginnote">RFC 9110 把语义从具体传输版本里抽出来。HTTP/1.1 的连接复用与 HTTP/2 的流共享同一套方法含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户端与代理按方法决定：失败的 GET 可重试；失败的 POST 要应用层保证。缓存键通常是方法+目标+相关头；<code>no-store</code> 禁止保存，<code>max-age</code> 给出新鲜期，验证器用条件 GET 把带宽换成确认。本课不把 Cookie 与会话当缓存替代。</p><p><span class="marginnote">直觉类比：幂等方法像电梯按钮——连按几次，效果都只是「电梯来这层」；非幂等的 POST 像支付按钮——手一抖按两次，钱就扣两回。这就是为什么网络设备敢自动重试 GET，而 POST 的重试必须由应用层自己拿主意。</span></p>',9)),(s(),A(l,null,{default:t(()=>[n(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20METH%5B%22%E6%96%B9%E6%B3%95%E8%AF%AD%E4%B9%89%22%5D%20--%3E%20IDEM%5B%22%E6%98%AF%E5%90%A6%E5%B9%82%E7%AD%89%20%2F%20%E5%AE%89%E5%85%A8%22%5D%0A%20%20IDEM%20--%3E%20RETRY%5B%22%E4%B8%AD%E9%97%B4%E4%BA%BA%E5%8F%AF%E5%90%A6%E8%87%AA%E5%8A%A8%E9%87%8D%E8%AF%95%22%5D%0A%20%20HDR%5B%22%E7%BC%93%E5%AD%98%E5%A4%B4%22%5D%20--%3E%20STORE%5B%22%E6%98%AF%E5%90%A6%E5%AD%98%E5%82%A8%E4%B8%8E%E5%86%8D%E9%AA%8C%E8%AF%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("幂等把"),e("a",{href:"/cs/layering-e2e"},"端到端"),E(" 重试从传输层（TCP 重传是字节，不是「再做一次业务」）里拆出来：TCP 保证段到达，HTTP 才规定「到达两次」是否事故。缓存把表示从源站路径上拿下来，后课 CDN 只是把缓存放到边上。TLS 入口仍只保护信道，不改方法语义。")],-1)),a[5]||(a[5]=e("p",null,"一份缓存副本从存下到复用，中间要过哪些判定？",-1)),(s(),A(l,null,{default:t(()=>[n(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%E7%BC%93%E5%AD%98%22%5D%20--%3E%20F%7B%22max-age%20%E5%86%85%E4%BB%8D%E6%96%B0%E9%B2%9C%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%E6%98%AF%7C%20HIT%5B%22%E7%9B%B4%E6%8E%A5%E8%BF%94%E5%9B%9E%E7%BC%93%E5%AD%98%E5%89%AF%E6%9C%AC%22%5D%0A%20%20F%20--%3E%7C%E5%90%A6%7C%20CV%5B%22%E5%B8%A6%20If-None-Match%20%E5%8F%91%E6%9D%A1%E4%BB%B6%20GET%22%5D%0A%20%20CV%20--%3E%20MATCH%7B%22%E6%BA%90%E7%AB%99%E6%AF%94%E5%AF%B9%20ETag%22%7D%0A%20%20MATCH%20--%3E%7C%22%E6%9C%AA%E5%8F%98%22%7C%20R304%5B%22304%EF%BC%9A%E5%8F%AA%E5%9B%9E%E7%A1%AE%E8%AE%A4%EF%BC%8C%E7%9C%81%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20MATCH%20--%3E%7C%22%E5%B7%B2%E5%8F%98%22%7C%20R200%5B%22200%EF%BC%9A%E5%9B%9E%E6%96%B0%E8%A1%A8%E7%A4%BA%E5%B9%B6%E6%9B%B4%E6%96%B0%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">术语翻译：ETag 就是资源内容的一枚「指纹」——内容变了指纹才变。缓存过期时不必重新下载整个文件，只要带着旧指纹问一句「还是这个吗」，源站回一个 304（没变）就能继续用本地副本，省下整份表示的带宽。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 REST 成熟度模型当协议，不引入 GraphQL。一条 TCP 连接上如何避免队头阻塞，下一课 HTTP/2。</p><p>后课默认：方法带幂等与缓存合同。多请求并行的传输映射是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RFC 9110：安全/幂等约束重试；缓存头约束存储。</li><li>传输重传 ≠ 应用重试。</li><li>多路复用下一课 HTTP/2。</li><li>出处：RFC 9110；Kurose and Ross。</li></ul><p><span class="marginnote">常见误区：初学者容易以为「TCP 可靠 = 请求不会重复执行」。TCP 的重传只保证字节到达对端；若响应在中途丢了、客户端超时重发整个 POST，服务端可能已经扣过一次款——到达两次字节，就是两次业务。这正是幂等语义要管的那一层。</span></p>',7))])}const f=i(d,[["render",p]]);export{F as __pageData,f as default};
